@testable import Platform

/// Every app, file and file type icon here is generated by ``SyntheticIconRenderer``. No test draws
/// a real app's icon or reads the user's files, and remote images come from a fake HTTP service.
@Suite(.timeLimit(.minutes(1))) struct IconTests {
    let root = TemporaryFolder()
    let renderer = CountingRenderer()
    let http = FakeHTTP()
    let settings = PlatformSettings(backend: MemorySettingsBackend())
    let watcher = FakeFileWatcher()

    var folders: IconCache.Folders {
        IconCache.Folders(
            atlas: root.url.appending(path: "atlas"), favicons: root.url.appending(path: "favicons"),
            remote: root.url.appending(path: "remote"))
    }

    static let apps = (1...3).map { index in
        AppIconEntry(bundleID: "com.example.app\(index)", url: nil, stamp: "v1")
    }

    func makeCache(apps: any AppIconSource = StaticAppIcons(IconTests.apps), memoryLimit: Int = 32 << 20)
        -> IconCache
    {
        IconCache(
            folders: folders, renderer: renderer, apps: apps, http: http, settings: settings, watcher: watcher,
            memoryLimit: memoryLimit, rebuildDelay: .milliseconds(10))
    }

    let row = IconSize(points: 28, scale: 2)

    @Test func drawnIconsArriveOffTheMainThreadAndSignal() async throws {
        let cache = makeCache()
        var changes = cache.changes.stream().makeAsyncIterator()
        #expect(cache.image(for: .symbol("star", tint: .accent), size: row, isDark: false) == nil)
        #expect(cache.image(for: .glyph("😀"), size: row, isDark: false) == nil)
        #expect(cache.image(for: .color(.rgba(red: 1, green: 0, blue: 0, alpha: 1)), size: row, isDark: false) == nil)
        await changes.next()
        let swatch = try await loaded {
            cache.image(for: .color(.rgba(red: 1, green: 0, blue: 0, alpha: 1)), size: row, isDark: false)
        }
        #expect(swatch.width == 56 && swatch.height == 56)
        #expect(center(of: swatch) == RGB(255, 0, 0))
        _ = try await loaded { cache.image(for: .symbol("star", tint: .accent), size: row, isDark: false) }
        _ = try await loaded { cache.image(for: .glyph("😀"), size: row, isDark: false) }
        // An unknown symbol fails once and is not tried again on every lookup.
        #expect(cache.image(for: .symbol("no.such.symbol.synthetic", tint: nil), size: row, isDark: false) == nil)
        _ = try await loaded { cache.isLoading ? nil : true }
        #expect(cache.image(for: .symbol("no.such.symbol.synthetic", tint: nil), size: row, isDark: false) == nil)
        #expect(!cache.isLoading)
        withExtendedLifetime(root) {}
    }

    @Test func appIconsComeFromAMappedAtlas() async throws {
        let cache = makeCache()
        #expect(cache.image(for: .app(bundleID: "com.example.app2"), size: row, isDark: false) == nil)
        let image = try await loaded { cache.atlas(pixels: 64)?.images["com.example.app2"] }
        #expect(cache.image(for: .app(bundleID: "com.example.app2"), size: row, isDark: true) === image)
        #expect(image.width == 64)
        #expect(center(of: image) == RGB(SyntheticIconRenderer.color(for: "app:com.example.app2")))
        #expect(cache.atlas(pixels: 64)?.count == 3)
        // Three for the atlas, and one drawn on its own for the lookup that came before it.
        _ = try await loaded { cache.isLoading ? nil : true }
        #expect(renderer.appDraws == 4)
        // An accessory-sized lookup uses the 32 pixel atlas.
        let small = try await loaded {
            cache.image(for: .app(bundleID: "com.example.app1"), size: IconSize(points: 16, scale: 2), isDark: false)
        }
        #expect(small.width == 32)
        withExtendedLifetime(root) {}
    }

    @Test func aSavedAtlasLoadsAtTheNextLaunchWithoutDrawing() async throws {
        let first = makeCache()
        _ = first.image(for: .app(bundleID: "com.example.app1"), size: row, isDark: false)
        let built = try await loaded { first.atlas(pixels: 64) }
        _ = try await loaded { first.isLoading ? nil : true }
        let draws = renderer.appDraws

        let relaunched = makeCache()
        relaunched.start()
        defer { relaunched.stop() }
        let loadedAtlas = try await loaded { relaunched.atlas(pixels: 64) }
        #expect(loadedAtlas.dataFile == built.dataFile)
        #expect(renderer.appDraws == draws)
        #expect(relaunched.image(for: .app(bundleID: "com.example.app3"), size: row, isDark: false) != nil)
        withExtendedLifetime(root) {}
    }

    @Test func aChangedAppListRebuildsTheAtlasAndKeepsUnchangedIcons() async throws {
        let apps = StaticAppIcons(Self.apps)
        let cache = makeCache(apps: apps)
        cache.start()
        defer { cache.stop() }
        _ = cache.image(for: .app(bundleID: "com.example.app1"), size: row, isDark: false)
        let old = try await loaded { cache.atlas(pixels: 64) }
        _ = try await loaded { cache.isLoading ? nil : true }
        let before = renderer.appDraws

        var changed = Self.apps
        changed[0].stamp = "v2"
        changed.append(AppIconEntry(bundleID: "com.example.app4", url: nil, stamp: "v1"))
        apps.set(changed)
        let rebuilt = try await loaded { cache.atlas(pixels: 64).flatMap { $0 === old ? nil : $0 } }
        #expect(rebuilt.count == 4)
        // Only the new app and the one whose stamp changed were drawn again.
        #expect(renderer.appDraws - before == 2)
        #expect(cache.image(for: .app(bundleID: "com.example.app4"), size: row, isDark: false) != nil)
        // The old file is gone from the folder but its images still draw.
        #expect(!FileManager.default.fileExists(atPath: old.dataFile.path(percentEncoded: false)))
        #expect(center(of: try #require(old.images["com.example.app2"])) != RGB(0, 0, 0))
        withExtendedLifetime(root) {}
    }

    @Test func appsOutsideTheAtlasAndLargeIconsAreDrawnOnTheirOwn() async throws {
        let cache = makeCache()
        let unlisted = Icon.app(bundleID: "com.example.unlisted")
        _ = cache.image(for: unlisted, size: row, isDark: false)
        let image = try await loaded { cache.image(for: unlisted, size: row, isDark: false) }
        #expect(image.width == 64)
        #expect(cache.atlas(pixels: 64)?.images["com.example.unlisted"] == nil)

        let large = try await loaded {
            cache.image(for: .app(bundleID: "com.example.app1"), size: IconSize(points: 64, scale: 2), isDark: false)
        }
        #expect(large.width == 128)
        withExtendedLifetime(root) {}
    }

    @Test func adaptiveIconsFollowTheAppearance() async throws {
        let cache = makeCache()
        let icon = Icon.adaptive(
            light: .color(.rgba(red: 1, green: 0, blue: 0, alpha: 1)),
            dark: .color(.rgba(red: 0, green: 0, blue: 1, alpha: 1)))
        let light = try await loaded { cache.image(for: icon, size: row, isDark: false) }
        let dark = try await loaded { cache.image(for: icon, size: row, isDark: true) }
        #expect(center(of: light) == RGB(255, 0, 0))
        #expect(center(of: dark) == RGB(0, 0, 255))
        withExtendedLifetime(root) {}
    }

    @Test func faviconsComeFromTheFolderWithAGlobeUntilThen() async throws {
        let cache = makeCache()
        cache.start()
        defer { cache.stop() }
        try await waitUntil { !watcher.watchedDirectories.isEmpty }
        let icon = Icon.favicon(domain: "www.Example.com")
        let globe = try await loaded { cache.image(for: icon, size: row, isDark: false) }
        #expect(center(of: globe) != RGB(255, 0, 0))

        try pngData(red: 255, green: 0, blue: 0).write(to: folders.favicons.appending(path: "example.com.png"))
        watcher.simulateChange([folders.favicons])
        let favicon = try await loaded {
            cache.image(for: icon, size: row, isDark: false).flatMap { center(of: $0) == RGB(255, 0, 0) ? $0 : nil }
        }
        #expect(favicon.width == 56)
        #expect(FaviconFolder.normalizedDomain("WWW.Example.COM.") == "example.com")
        withExtendedLifetime(root) {}
    }

    @Test func remoteImagesDownloadOnceAndFollowTheSetting() async throws {
        let cache = makeCache()
        cache.start()
        defer { cache.stop() }
        let url = try #require(URL(string: "https://example.com/icon.png"))
        http.stub(url, response: HTTPResponse(status: 200, body: try pngData(red: 0, green: 255, blue: 0)))
        let small = try await loaded {
            cache.image(for: .remote(url), size: IconSize(points: 16, scale: 2), isDark: false)
        }
        let large = try await loaded { cache.image(for: .remote(url), size: row, isDark: false) }
        #expect(center(of: small) == RGB(0, 255, 0) && center(of: large) == RGB(0, 255, 0))
        #expect(http.requests.count == 1)

        // Turned off: no download, a placeholder instead. Turned on: the download happens.
        let other = try #require(URL(string: "https://example.com/other.png"))
        http.stub(other, response: HTTPResponse(status: 200, body: try pngData(red: 0, green: 0, blue: 255)))
        HostSettings.settings(settings)[HostSettings.fetchRemoteIcons] = false
        let placeholder = try await loaded { cache.image(for: .remote(other), size: row, isDark: false) }
        #expect(center(of: placeholder) != RGB(0, 0, 255))
        #expect(http.requests.count == 1)
        HostSettings.settings(settings)[HostSettings.fetchRemoteIcons] = true
        _ = try await loaded {
            cache.image(for: .remote(other), size: row, isDark: false).flatMap {
                center(of: $0) == RGB(0, 0, 255) ? $0 : nil
            }
        }
        #expect(http.requests.count == 2)

        // Plain http is never fetched.
        let insecure = try #require(URL(string: "http://example.com/icon.png"))
        _ = try await loaded { cache.image(for: .remote(insecure), size: row, isDark: false) }
        #expect(http.requests.count == 2)
        withExtendedLifetime(root) {}
    }

    @Test func theMemoryCacheStaysWithinItsLimit() async throws {
        let limit = Bitmap.byteCount(pixels: 56) * 4
        let cache = makeCache(memoryLimit: limit)
        for step in 0..<10 {
            let icon = Icon.color(.rgba(red: Double(step) / 10, green: 0, blue: 0, alpha: 1))
            _ = try await loaded { cache.image(for: icon, size: row, isDark: false) }
            #expect(cache.memoryCacheBytes <= limit)
        }
        #expect(cache.memoryCacheCount <= 4)
        withExtendedLifetime(root) {}
    }

    @Test func prepareLoadsAhead() async throws {
        let cache = makeCache()
        cache.prepare([.glyph("A"), .symbol("star", tint: nil)], size: row)
        _ = try await loaded { cache.isLoading ? nil : true }
        #expect(cache.image(for: .glyph("A"), size: row, isDark: false) != nil)
        #expect(cache.image(for: .symbol("star", tint: nil), size: row, isDark: true) != nil)
        withExtendedLifetime(root) {}
    }

    @Test func aDamagedAtlasIsIgnored() throws {
        let folder = folders.atlas
        let atlas = try IconAtlas.build(Self.apps, pixels: 32, renderer: renderer, reusing: nil, in: folder)
        #expect(IconAtlas.load(from: folder, pixels: 32)?.count == 3)
        try Data(count: 10).write(to: atlas.dataFile)
        #expect(IconAtlas.load(from: folder, pixels: 32) == nil)
        try Data("not json".utf8).write(to: IconAtlas.indexURL(in: folder, pixels: 32))
        #expect(IconAtlas.load(from: folder, pixels: 32) == nil)
        withExtendedLifetime(root) {}
    }

    @Test func sizesAndAppearanceRules() {
        #expect(IconCache.bucket(for: 16) == 0 && IconCache.bucket(for: 32) == 0)
        #expect(IconCache.bucket(for: 56) == 1 && IconCache.bucket(for: 64) == 1)
        #expect(IconCache.bucket(for: 65) == nil)
        #expect(IconCache.dependsOnAppearance(.symbol("star", tint: nil)))
        #expect(IconCache.dependsOnAppearance(.color(.accent)))
        #expect(!IconCache.dependsOnAppearance(.symbol("star", tint: .rgba(red: 1, green: 0, blue: 0, alpha: 1))))
        #expect(!IconCache.dependsOnAppearance(.app(bundleID: "com.example.app1")))
        #expect(IconCache.resolve(.adaptive(light: .glyph("L"), dark: .glyph("D")), isDark: true) == .glyph("D"))
    }

}

/// Polls a lookup on the main actor until it returns something, for up to five seconds.
func loaded<T>(_ lookup: () -> T?, sourceLocation: SourceLocation = #_sourceLocation) async throws -> T {
    let deadline = ContinuousClock.now + .seconds(5)
    while true {
        if let value = lookup() { return value }
        guard ContinuousClock.now < deadline else {
            Issue.record("still not loaded after 5 s", sourceLocation: sourceLocation)
            throw CancellationError()
        }
        try await Task.sleep(for: .milliseconds(5))
    }
}

/// An 8-bit color, for comparing pixels. Two colors are equal when no channel differs by more
/// than 3, which absorbs rounding in color conversion and scaling.
struct RGB: Equatable, CustomStringConvertible {
    var red: UInt8
    var green: UInt8
    var blue: UInt8

    init(_ red: UInt8, _ green: UInt8, _ blue: UInt8) {
        self.red = red
        self.green = green
        self.blue = blue
    }

    init(_ color: (red: UInt8, green: UInt8, blue: UInt8)) {
        self.init(color.red, color.green, color.blue)
    }

    var description: String { "rgb(\(red), \(green), \(blue))" }

    static func == (left: RGB, right: RGB) -> Bool {
        abs(Int(left.red) - Int(right.red)) <= 3 && abs(Int(left.green) - Int(right.green)) <= 3
            && abs(Int(left.blue) - Int(right.blue)) <= 3
    }
}

/// The color of an image's center pixel.
func center(of image: CGImage) -> RGB {
    let side = 1
    var pixel = [UInt8](repeating: 0, count: 4)
    pixel.withUnsafeMutableBytes { buffer in
        guard let context = Bitmap.context(pixels: side, data: buffer.baseAddress) else { return }
        context.interpolationQuality = .none
        let width = CGFloat(image.width)
        let height = CGFloat(image.height)
        context.draw(image, in: CGRect(x: -width / 2 + 0.5, y: -height / 2 + 0.5, width: width, height: height))
    }
    // BGRA in memory.
    return RGB(pixel[2], pixel[1], pixel[0])
}

/// A small PNG of one color.
func pngData(red: UInt8, green: UInt8, blue: UInt8) throws -> Data {
    let image = try #require(
        Bitmap.image(pixels: 8) { context in
            context.setFillColor(
                CGColor(srgbRed: CGFloat(red) / 255, green: CGFloat(green) / 255, blue: CGFloat(blue) / 255, alpha: 1))
            context.fill(CGRect(x: 0, y: 0, width: 8, height: 8))
            return true
        })
    let data = NSMutableData()
    let destination = try #require(CGImageDestinationCreateWithData(data, "public.png" as CFString, 1, nil))
    CGImageDestinationAddImage(destination, image, nil)
    #expect(CGImageDestinationFinalize(destination))
    return data as Data
}

/// The synthetic renderer, counting how many app icons it drew.
nonisolated final class CountingRenderer: IconRenderer {
    private let draws = Mutex(0)
    private let synthetic = SyntheticIconRenderer()

    var appDraws: Int { draws.withLock { $0 } }

    func drawApplication(bundleID: String, at url: URL?, in context: CGContext, pixels: Int) -> Bool {
        draws.withLock { $0 += 1 }
        return synthetic.drawApplication(bundleID: bundleID, at: url, in: context, pixels: pixels)
    }

    func file(at path: String, pixels: Int) -> CGImage? {
        synthetic.file(at: path, pixels: pixels)
    }

    func fileType(_ type: String, pixels: Int) -> CGImage? {
        synthetic.fileType(type, pixels: pixels)
    }
}
